func TestOCBSpecVectors(t *testing.T) {
	for _, tc := range ocbVectors {
		key := mustHex(t, tc.key)
		nonce := mustHex(t, tc.nonce)
		ad := mustHex(t, tc.ad)
		pt := mustHex(t, tc.pt)
		want := mustHex(t, tc.ct)
		o, err := NewOCB(key)
		if err != nil {
			t.Fatalf("NewOCB: %v", err)
		}
		got := make([]byte, len(pt)+TagSize)
		if err := o.Seal(got, nonce, ad, pt); err != nil {
			t.Fatalf("Seal: %v", err)
		}
		if string(got) != string(want) {
			t.Errorf("Seal(pt=%x ad=%x):\n got %x\nwant %x", pt, ad, got, want)
		}
		opened := make([]byte, len(pt))
		if err := o.Open(opened, nonce, ad, want); err != nil {
			t.Errorf("Open(pt=%x): %v", pt, err)
			o.Destroy()
			continue
		}
		if string(opened) != string(pt) {
			t.Errorf("Open(pt=%x): got %x", pt, opened)
		}
		o.Destroy()
	}
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	if s == "" {
		return nil
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}
